import sys

def solve(n, m):
    if n % 2 == 0 or m % 2 == 0:
        k = 0
        path = []
        x, y = 1, 1
        path.append((x, y))
        dx, dy = 0, 1
        while len(path) < n * m + 1:
            nx, ny = x + dx, y + dy
            if not (1 <= nx <= n and 1 <= ny <= m):
                if dy == 1:
                    dx, dy = 1, 0
                elif dx == 1:
                    dx, dy = 0, -1
                elif dy == -1:
                    dx, dy = -1, 0
                elif dx == -1:
                    dx, dy = 0, 1
                nx, ny = x + dx, y + dy
            path.append((nx, ny))
            x, y = nx, ny
    else:
        k = 1
        path = [(1, 1)]
        for i in range(1, n * m + 1):
            x = (i - 1) // m + 1
            y = (i - 1) % m + 1
            if x == n and y == m:
                path.append((1, 1))
            else:
                path.append((x, y))
        path.append((1, 1))

    return k, path

def main():
    import sys
    input = sys.stdin.read().strip()
    n, m = map(int, input.split())
    k, path = solve(n, m)
    print(k)
    if k > 0:
        print(f"{n} {m} 1 1")
    for x, y in path:
        print(x, y)

if __name__ == "__main__":
    main()
